const fs=require('node:fs'),path=require('node:path');
async function main(){const pages=(await(await fetch('http://127.0.0.1:57218/json/list')).json()).filter(t=>t.type==='page'&&t.url.includes('/apps/pc-app/dist/ui/index.html'));if(pages.length!==1)throw Error('Unique original CloudA renderer required');
const expression=`(async()=>{const r=await window.lingjing.invoke('app','info');const d=r.data||r;const s=await window.lingjing.invoke('accounts','session');const x=s.data||s;const u=x.currentUser||null;return {ok:r.ok,version:d.version,build:d.build,runtime:d.runtime,scenario:d.scenario??null,user:d.user?{ownerAccountId:d.user.ownerAccountId,provider:d.user.provider,authUserId:d.user.authUserId,deviceId:d.user.deviceId,sessionId:d.user.sessionId}:null,publicSession:{dataMode:x.dataMode,persistence:x.persistence,user:u?{ownerAccountId:u.ownerAccountId,provider:u.provider,authUserId:u.authUserId,deviceId:u.deviceId,sessionId:u.sessionId}:null},route:location.hash,visibleAlerts:[...document.querySelectorAll('[role=alert]')].map(e=>e.innerText),visibleStatus:[...document.querySelectorAll('[role=status]')].map(e=>e.innerText)}})()`;
const ws=new WebSocket(pages[0].webSocketDebuggerUrl);const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{ws.close();reject(Error('Readonly timeout'));},10000);ws.onopen=()=>ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{returnByValue:true,awaitPromise:true,expression}}));ws.onerror=()=>{clearTimeout(timer);reject(Error('Readonly connection failed'));};ws.onmessage=e=>{const r=JSON.parse(e.data);if(r.id!==1)return;clearTimeout(timer);ws.close();if(r.error||r.result?.exceptionDetails)reject(Error('Readonly projection failed'));else resolve(r.result.result.value);};});
const report={at:new Date().toISOString(),method:'Readonly public app:info/accounts:session safe projection; no credential/proof values returned, input or business mutation',result};const output=path.join(__dirname,'cloudA-app-info-'+process.argv[2]+'-20261026.json');fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({output,...report}));}
main().catch(e=>{console.error(e.message);process.exitCode=1;});
